"""Curated source-grounded rules. Rebuild rules.json and readable RULE-CATALOG.md."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[1]
RULES=[]
def ref(source,number,section=False):
    return {'source_id':source,'locator':f'{"section" if section else "page"}-{number:04d}'}
def j(n): return ref('vastu-jain',n,True)
def p(): return ref('vastu-pathi',8,True)
def s(n): return ref('vastu-svoboda',n,True)
def c(n): return ref('vastu-chakrabarti',n)
def add(id,title,tier,tags,sources,principle,test,repair,conflict='',predicate=None,applies=None):
    RULES.append(dict(id=id,title=title,tier=tier,tags=tags.split(),sources=sources,
      principle=principle,measurement=test,repair=repair,conflict=conflict or 'No consensus claim; apply the selected household profile and mandatory safety constraints.',
      provenance='source_paraphrase_with_keystone_operationalization',
      review_status='curated_not_professionally_approved',predicate=predicate,applies_when=applies))
def pred(fact,op,value): return dict(fact=fact,op=op,value=value)
def optional(name): return pred(name+'.requested','eq',True)

