add('G01','Confirm local adoption and municipal overlay',0,'jurisdiction coverage setback code',[ref('nbc206-2024',1),ref('nbc206-2024',5)],'Use applicable national provisions plus municipal rules; shared valley geography does not prove identical bylaws.','Record municipality, ward, rule versions and reviewer confirmation.','Resolve missing overlay before compliance claims.',predicate=pred('jurisdiction.reviewed','eq',True))
