POLICY={
 'version':'np-vastu-first-0.1',
 'priority_order':['0 mandatory legal/safety feasibility and confirmed engineering','1 Vaastu core spatial organization','2 Vaastu fixture/detail preferences','3 other architectural/presentation preferences'],
 'selection':'Lexicographic preference ranking only after complete applicable critical checks. User-required program/essential preferences are hard constraints; conflicts require explicit resolution.',
 'default_tradition':'Jain-led spatial profile with corroboration and explicit Pathi/Chakrabarti/Svoboda disagreements; not a consensus or professional approval.',
 'unknown_policy':'Missing applicability, measurements, source interpretation or local adoption never pass.',
 'claims':'Directional beliefs are treated as cultural preferences. No medical, financial, seismic or supernatural outcome is asserted.',
 'scope':'Local retrieval and fact evaluation only; not connected to production plan generation.'}

def build():
    manifest={m['id']:m for m in json.loads((ROOT/'manifest.json').read_text(encoding='utf-8'))}
    for rule in RULES:
        for source in rule['sources']:
            source['sha256']=manifest[source['source_id']]['sha256']
    out={'schema_version':1,'policy':POLICY,'rules':RULES}
    (ROOT/'rules.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    lines=['# Source-linked house-design rule catalog','',f'{len(RULES)} curated rules. Highest design preference: Vaastu. Mandatory legal/safety constraints remain gates. Source facts and Keystone operationalization are distinguished in each rule. No professional approval is claimed.','', 'Read [the synthesis](DESIGN-PRINCIPLES.md) and [integration contract](INTEGRATION.md) before using these rules.','']
    for r in RULES:
        links=', '.join(f'[{x["source_id"]} {x["locator"]}](sources/{x["source_id"]}.md#{x["locator"]})' for x in r['sources'])
        lines += [f'## {r["id"]} — {r["title"]}', '',f'Priority tier: **{r["tier"]}**. Tags: '+', '.join(r['tags']), '',r['principle'],'',f'**Measure:** {r["measurement"]}', '',f'**Repair:** {r["repair"]}', '',f'**Interpretation/conflict:** {r["conflict"]}', '',f'**Sources:** {links}', '']
        if r['predicate']: lines += ['**Executable fact predicate:** `'+json.dumps(r['predicate'],ensure_ascii=False)+'`.','']
        if r['applies_when']: lines += ['**Applicability:** `'+json.dumps(r['applies_when'])+'`.','']
    (ROOT/'RULE-CATALOG.md').write_text('\n'.join(lines),encoding='utf-8')
    print(f'Built {len(RULES)} rules')

if __name__=='__main__':build()
